param([switch]$List,[string]$InputPath,[string]$OutputPath)
$ErrorActionPreference='Stop'
[Console]::OutputEncoding=New-Object Text.UTF8Encoding($false)
Add-Type -AssemblyName System.Speech
$studioSpeech=New-Object System.Speech.Synthesis.SpeechSynthesizer
try {
  if($List){
    @($studioSpeech.GetInstalledVoices() | Where-Object {$_.Enabled} | ForEach-Object {@{name=$_.VoiceInfo.Name;language=$_.VoiceInfo.Culture.Name}}) | ConvertTo-Json -Compress
    exit 0
  }
  # Payload is JSON data, never command text or SSML. Paths are generated by the trusted worker.
  $studioVoiceInput=[IO.File]::ReadAllText($InputPath,[Text.Encoding]::UTF8) | ConvertFrom-Json
  if($studioVoiceInput.text.Length -lt 1 -or $studioVoiceInput.text.Length -gt 50000){throw 'VOICE_TEXT_LIMIT'}
  if($studioVoiceInput.rate -lt -10 -or $studioVoiceInput.rate -gt 10){throw 'VOICE_RATE_INVALID'}
  $studioSpeech.SelectVoice([string]$studioVoiceInput.voice)
  $studioSpeech.Rate=[int]$studioVoiceInput.rate
  $studioSpeech.SetOutputToWaveFile($OutputPath)
  $studioSpeech.Speak([string]$studioVoiceInput.text)
} finally {$studioSpeech.Dispose()}
